CREATE TABLE [sales].[CustomerPaymentTerms] ([PaymentTermId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_CustomerPaymentTerms_Id] DEFAULT NEWSEQUENTIALID(),[PaymentTermCode] NVARCHAR(30) NOT NULL,[PaymentTermName] NVARCHAR(100) NOT NULL,[DueDays] INT NOT NULL,[IsDefault] BIT NOT NULL CONSTRAINT [DF_CustomerPaymentTerms_Default] DEFAULT 0,[IsActive] BIT NOT NULL CONSTRAINT [DF_CustomerPaymentTerms_Active] DEFAULT 1,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_CustomerPaymentTerms_Created] DEFAULT SYSUTCDATETIME(),[CreatedBy] NVARCHAR(256) NULL,[ModifiedOn] DATETIMEOFFSET NULL,[ModifiedBy] NVARCHAR(256) NULL,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_CustomerPaymentTerms] PRIMARY KEY([PaymentTermId]),CONSTRAINT [CK_CustomerPaymentTerms_Days] CHECK([DueDays]>=0));
GO
CREATE UNIQUE INDEX [UX_CustomerPaymentTerms_Code] ON [sales].[CustomerPaymentTerms]([PaymentTermCode]);
